const aiItems = $input.all();
const formItems = $('New Form Submission').all();

function cleanMarkers(text = '') {
  return String(text || '')
    .replace(/TITLE\s*:/gi, '')
    .replace(/TEXT\s*:/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function cleanStrangeChars(text = '') {
  return String(text || '')
    .replace(/[^\u0600-\u06FF0-9\s،؛؟.!:"'()\-]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function getParticipantName(formRow = {}) {
  return (
    formRow['الأسم'] ||
    formRow['الاسم'] ||
    formRow['الإسم'] ||
    formRow['اسم'] ||
    formRow['اسم المشارك'] ||
    Object.entries(formRow).find(([key]) =>
      String(key).replace(/\s/g, '').includes('اسم')
    )?.[1] ||
    ''
  );
}

return aiItems.map((item, index) => {
  const aiOutput = String(item.json.output || '');
  const formRow = formItems[index]?.json || {};

  let aiTitle = 'ومضة علم';
  let aiText = aiOutput;

  // Extract title
  const titleMatch = aiOutput.match(/TITLE:\s*(.*)/i);
  if (titleMatch) {
    aiTitle = titleMatch[1].trim();
  }

  // Extract text
  const textMatch = aiOutput.match(/TEXT:\s*([\s\S]*)/i);
  if (textMatch) {
    aiText = textMatch[1].trim();
  }

  // Clean title and text
  aiTitle = cleanStrangeChars(cleanMarkers(aiTitle));
  aiText = cleanStrangeChars(cleanMarkers(aiText));

  // Get participant name from sheet
  const participantName = String(getParticipantName(formRow)).trim();

  return {
    json: {
      ...formRow,
      aiTitle,
      aiText,
      participantName,
      status: 'Processed'
    }
  };
});

function escapeHtml(text = '') {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function cleanText(text = '') {
  return String(text || '')
    .replace(/TITLE\s*:/gi, '')
    .replace(/TEXT\s*:/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function findName(row = {}) {
  const keys = Object.keys(row);

  const direct =
    row['الأسم'] ||
    row['الاسم'] ||
    row['الإسم'] ||
    row['اسم'] ||
    row['اسم المشارك'];

  if (direct) return cleanText(direct);

  const nameKey = keys.find(k =>
    k.replace(/\s/g, '').includes('اسم') ||
    k.replace(/\s/g, '').includes('الأسم') ||
    k.replace(/\s/g, '').includes('الاسم')
  );

  return nameKey ? cleanText(row[nameKey]) : '';
}

const formItems = $('New Form Submission').all();
const parsedItems = $('Parse AI Result').all();

const totalItems = Math.max(formItems.length, parsedItems.length);

return Array.from({ length: totalItems }, (_, index) => {
  const formRow = formItems[index]?.json || {};
  const parsed = parsedItems[index]?.json || {};

  const title = cleanText(
    parsed.aiTitle ||
    parsed['AI Title'] ||
    formRow['AI Title'] ||
    'عنوان الومضة'
  );

  const bodyText = cleanText(
    parsed.aiText ||
    parsed['AI Output'] ||
    formRow['AI Output'] ||
    'لا يوجد نص لعرضه.'
  );

  const author = cleanText(
    parsed.participantName ||
    parsed['الأسم'] ||
    parsed['الاسم'] ||
    findName(formRow)
  );

  const displayAuthor = author || 'لم يتم سحب الاسم';

  const svg = `
  <svg width="1080" height="1080" viewBox="0 0 1080 1080" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <linearGradient id="bg-${index}" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stop-color="#0A7FEF"/>
        <stop offset="100%" stop-color="#0759B9"/>
      </linearGradient>

      <linearGradient id="dark-${index}" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stop-color="#073C76"/>
        <stop offset="100%" stop-color="#052D5D"/>
      </linearGradient>

      <style>
        .arabic {
          font-family: Tahoma, Arial, sans-serif;
          direction: rtl;
          text-align: right;
          color: white;
          box-sizing: border-box;
        }

        .hashtag {
          font-size: 30px;
          font-weight: 800;
          line-height: 1.2;
        }

        .title {
          font-size: 46px;
          font-weight: 900;
          line-height: 1.25;
        }

        .author {
          display: inline-block;
          background: rgba(0,0,0,0.48);
          border-radius: 5px;
          padding: 7px 14px;
          font-size: 24px;
          font-weight: 800;
          line-height: 1.2;
        }

        .body {
          font-size: 25px;
          font-weight: 700;
          line-height: 1.55;
          white-space: normal;
          overflow: hidden;
        }

        .club-main {
          font-size: 36px;
          font-weight: 900;
          line-height: 1.1;
        }

        .club-sub {
          font-size: 20px;
          font-weight: 600;
          opacity: 0.9;
          margin-top: 6px;
        }
      </style>
    </defs>

    <rect width="1080" height="1080" fill="url(#bg-${index})"/>

    <polygon points="0,0 1080,0 1080,520 900,620 0,80" fill="#0B64C6" opacity="0.38"/>
    <polygon points="0,120 165,40 1035,560 870,645" fill="#1B8CFF" opacity="0.62"/>
    <polygon points="45,240 1045,760 1045,1080 45,1080" fill="url(#dark-${index})"/>

    <foreignObject x="620" y="130" width="390" height="60">
      <div xmlns="http://www.w3.org/1999/xhtml" class="arabic hashtag">
        💡 #ومضة_علم
      </div>
    </foreignObject>

    <foreignObject x="250" y="190" width="735" height="130">
      <div xmlns="http://www.w3.org/1999/xhtml" class="arabic title">
        ${escapeHtml(title)}
      </div>
    </foreignObject>

    <foreignObject x="630" y="315" width="360" height="65">
      <div xmlns="http://www.w3.org/1999/xhtml" class="arabic">
        <span class="author">${escapeHtml(displayAuthor)} ✍</span>
      </div>
    </foreignObject>

    <foreignObject x="105" y="410" width="850" height="390">
      <div xmlns="http://www.w3.org/1999/xhtml" class="arabic body">
        ${escapeHtml(bodyText)}
      </div>
    </foreignObject>

    <foreignObject x="720" y="875" width="280" height="100">
      <div xmlns="http://www.w3.org/1999/xhtml" class="arabic">
        <div class="club-main">نادي علم</div>
        <div class="club-sub">الافتراضي الطلابي</div>
      </div>
    </foreignObject>
  </svg>
  `;

  const fileName = `wamdat-elm-${index + 1}.svg`;

  return {
    json: {
      fileName,
      title,
      bodyText,
      author,
      displayAuthor,
      formKeys: Object.keys(formRow)
    },
    binary: {
      canva_image: {
        data: Buffer.from(svg, 'utf8').toString('base64'),
        mimeType: 'image/svg+xml',
        fileName
      }
    }
  };
});
